css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
.split{ display: grid; grid-template-columns: minmax(180px, 1fr) minmax(0, 920px); column-gap: 64px; row-gap: 24px; align-items: start; }
.split-body{ min-width: 0; }
.label{ margin: 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.25; font-weight: 500; letter-spacing: 0.04em; text-transform: uppercase; max-width: 320px; }
.lead{ margin: 0 0 32px 0; font-family: Switzer, Arial, sans-serif; font-size: 40px; line-height: 1.18; font-weight: 400; letter-spacing: -0.02em; }
.body-text{ margin: 0 0 16px 0; font-family: Switzer, Arial, sans-serif; font-size: 18px; line-height: 1.6; font-weight: 400; max-width: 760px; }
.embed-slot{ display: block; width: 100%; }
@media screen and (max-width: 991px){.split{ grid-template-columns: minmax(0, 1fr); row-gap: 20px; }
.lead{ font-size: 34px; }}
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }
.label{ font-size: 15px; }
.lead{ font-size: 28px; margin-bottom: 24px; }
.body-text{ font-size: 17px; }}
@media screen and (max-width: 479px){.lead{ font-size: 25px; }}
.how-section { padding-top: 150px; padding-bottom: 150px; background-color: #13181d; color: #ffffff; font-family: Switzer, Arial, sans-serif; scroll-margin-top: 120px; }
.process-panel { margin-top: 96px; padding: 48px; border-radius: 4px; background-color: #d1d1d1; color: #13181d; }
.phase-heading-build { display: inline-block; margin: 0 0 20px 0; padding: 6px 14px; border-radius: 999px; background-color: #1bc594; font-size: 13px; line-height: 1.2; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; color: #13181d; }
.phase-heading-use { display: inline-block; margin: 0 0 20px 0; padding: 6px 14px; border-radius: 999px; background-color: #13181d; font-size: 13px; line-height: 1.2; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; color: #ffffff; }
.steps-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
.step-card { display: flex; flex-direction: column; align-items: flex-start; padding: 28px; border-radius: 4px; background-color: #e4e4e4; }
.step-number-build { margin: 0 0 18px 0; padding: 3px 10px; border-radius: 999px; background-color: #1bc594; font-size: 13px; line-height: 1.3; font-weight: 600; color: #13181d; }
.step-number-use { margin: 0 0 18px 0; padding: 3px 10px; border-radius: 999px; background-color: #13181d; font-size: 13px; line-height: 1.3; font-weight: 600; color: #ffffff; }
.step-name { margin: 0 0 10px 0; font-size: 24px; line-height: 1.2; font-weight: 400; }
.step-text { margin: 0; font-size: 16px; line-height: 1.55; color: rgba(19, 24, 29, 0.85); }
.handoff-row { display: flex; align-items: center; gap: 16px; margin: 36px 0; }
.handoff-line { flex: 1 1 0; height: 1px; background-color: rgba(19, 24, 29, 0.3); }
.handoff-pill { padding: 6px 14px; border: 1px solid rgba(19, 24, 29, 0.5); border-radius: 999px; font-size: 14px; line-height: 1.3; text-align: center; }
.predict-area { margin-top: 32px; scroll-margin-top: 140px; }

@media screen and (max-width: 991px) {
  .how-section { padding-top: 112px; padding-bottom: 112px; }
  .process-panel { margin-top: 64px; padding: 40px; }
  .steps-row { gap: 14px; }
  .step-card { padding: 22px; }
  .step-name { font-size: 21px; }
  .step-text { font-size: 15px; }
}
@media screen and (max-width: 767px) {
  .how-section { padding-top: 88px; padding-bottom: 88px; }
  .process-panel { margin-top: 48px; padding: 24px 20px; }
  .steps-row { grid-template-columns: minmax(0, 1fr); gap: 12px; }
  .step-text { font-size: 16px; }
  .handoff-row { margin: 28px 0; gap: 10px; }
  .predict-area { margin-top: 24px; }
}
@media screen and (max-width: 479px) {
  .process-panel { margin-left: -8px; margin-right: -8px; padding: 20px 14px; }
  .handoff-pill { font-size: 13px; }
}
